"use client";
import { useId, useState } from "react";
import { Area, ComposedChart, Line, ResponsiveContainer, Tooltip, YAxis } from "recharts";
import { Chip } from "../../base/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/cx";
import { ChartActiveDot } from "./chart-active-dot";
import { CardSurface } from "./card-surface";
import { WeekSwitcher } from "./pro-chart";
import { useChartHover } from "./chart-card";

export interface HistoryMonth {
  month: number;
  total: number;
  points: { height: number; value: number }[];
}
export interface HistoryPoint {
  label: string;
  value: number;
}
export function DailyHistoryCard({
  kind,
  months = [],
  data = [],
  summary = 667.7,
  delta = "+9.4%",
  defaultLabel = "Tokens",
  labels = ["Jun 14", "Today"],
  plotHeight = 200,
  gapRanges,
  animateSummaryOnMount = true,
}: {
  kind: "agents" | "tokens";
  months?: HistoryMonth[];
  data?: HistoryPoint[];
  summary?: number;
  delta?: string;
  defaultLabel?: string;
  labels?: readonly [string, string];
  plotHeight?: number;
  gapRanges?: readonly (readonly [number, number])[];
  animateSummaryOnMount?: boolean;
}) {
  const [month, setMonth] = useState(11),
    [active, setActive] = useState<number | null>(null),
    hover = useChartHover(),
    id = useId();
  const agents = kind === "agents",
    current = months.find((m) => m.month === month) ?? months[0],
    index = agents ? active : hover.activeIndex;
  const target =
    index == null
      ? agents
        ? (current?.total ?? 0)
        : summary
      : agents
        ? (current?.points[index]?.value ?? 0)
        : (data[index]?.value ?? 0);
  const display = useCountUp(
    target,
    320,
    false,
    false,
    animateSummaryOnMount ? { value: 0, duration: 1560 } : undefined,
  );
  const monthLabel = new Date(2026, month).toLocaleDateString("en-US", { month: "long" });
  const label =
    index == null
      ? agents
        ? "Agents"
        : defaultLabel
      : agents
        ? `${monthLabel.slice(0, 3)} ${index + 1}`
        : (data[index]?.label ?? "Tokens");
  const runs: { key: string; start: number; end: number; gap: boolean }[] = gapRanges
    ? []
    : [
        { key: "lead", start: 0, end: 3, gap: false },
        { key: "gap", start: 3, end: 11, gap: true },
        { key: "tail", start: 11, end: data.length - 1, gap: false },
      ];
  if (gapRanges) {
    let cursor = 0;
    for (const [start, end] of gapRanges) {
      runs.push(
        { key: `run-${runs.length}`, start: cursor, end: start, gap: false },
        { key: `run-${runs.length + 1}`, start, end, gap: true },
      );
      cursor = end;
    }
    runs.push({ key: `run-${runs.length}`, start: cursor, end: data.length - 1, gap: false });
  }
  const plot = data.map((p, i) => ({
    ...p,
    ...Object.fromEntries(
      runs.map((run) => [run.key, i >= run.start && i <= run.end ? p.value : null]),
    ),
  }));
  const header = (
    <div className={cx("flex min-w-0 flex-1 flex-col gap-0.5")}>
      <p className="text-body-medium whitespace-nowrap text-text-secondary">{label}</p>
      <div className="flex items-center gap-2">
        <p
          key={`${month}:${index}`}
          className="animate-number-fade text-title-2-medium whitespace-nowrap text-text-primary tabular-nums"
        >
          {agents ? Math.round(display) : display.toFixed(1)}
          {agents ? " agents" : "M tokens"}
        </p>
        {!agents && (
          <Chip color="purple" variant="bold">
            {delta}
          </Chip>
        )}
      </div>
    </div>
  );
  return (
    <CardSurface
      padding="none"
      className={cx(
        "relative flex w-full shrink-0 flex-col rounded-[20px] py-3",
        agents && "gap-2.5 px-2.5",
      )}
    >
      <div
        className={agents ? "flex w-full px-1.5 pt-1" : "relative z-10 -mb-8 flex w-full px-4 pt-1"}
      >
        {header}
      </div>
      {agents ? (
        <>
          <WeekSwitcher
            compact
            label={monthLabel}
            className="absolute top-4 end-4 w-[128px]"
            onPrevious={() => {
              setMonth((m) => (m + 11) % 12);
              setActive(null);
            }}
            onNext={() => {
              setMonth((m) => (m + 1) % 12);
              setActive(null);
            }}
          />
          <div
            className="flex w-full items-end gap-[7px]"
            style={{ height: 206 }}
            onMouseLeave={() => setActive(null)}
          >
            {current?.points.map((point, i) => (
              <div
                key={`${month}-${i}`}
                className="flex h-full min-w-0 flex-1 items-end rounded-sm"
                onMouseEnter={() => setActive(i)}
              >
                <div
                  className={cx(
                    "animate-bar-rise w-full rounded-sm transition-[height,background-color] duration-300 ease",
                    point.value === 0
                      ? index === i
                        ? "bg-chart-cursor"
                        : "bg-chart-track"
                      : index === i
                        ? "bg-chart-agents-bar-active"
                        : "bg-chart-agents-bar",
                  )}
                  style={{ height: point.height, animationDelay: `${i * 22}ms` }}
                />
              </div>
            ))}
          </div>
        </>
      ) : (
        <div className="w-full animate-chart-reveal" style={{ height: plotHeight }}>
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={plot}
              margin={{ top: 27, left: 0, right: 0, bottom: 2 }}
              {...hover.handlers}
            >
              <defs>
                <linearGradient id={id} x1="0" x2="0" y1="0" y2="1">
                  <stop offset="0%" stopColor="var(--color-purple-400)" stopOpacity={0.32} />
                  <stop offset="100%" stopColor="var(--color-purple-400)" stopOpacity={0} />
                </linearGradient>
              </defs>
              <YAxis hide domain={[0, 60]} />
              <Tooltip content={() => null} cursor={false} />
              <Area
                dataKey="value"
                type="linear"
                fill={`url(#${id})`}
                fillOpacity={0.6}
                stroke="none"
                isAnimationActive={false}
              />
              {runs.map(({ key, gap }) => (
                <Line
                  key={key}
                  dataKey={key}
                  type="linear"
                  stroke={gap ? "var(--color-neutral-400)" : "var(--color-purple-400)"}
                  strokeWidth={2}
                  strokeDasharray={gap ? "5 5" : undefined}
                  dot={false}
                  activeDot={(p) => (
                    <ChartActiveDot
                      {...p}
                      fill={gap ? "var(--color-neutral-400)" : "var(--color-purple-500)"}
                    />
                  )}
                  isAnimationActive={false}
                />
              ))}
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      )}
      <div
        className={cx(
          "flex w-full items-start justify-between text-[11px] leading-[15px] font-medium tracking-[0.2px] whitespace-nowrap text-text-tertiary",
          agents ? "px-1.5" : "mt-2 px-4",
        )}
      >
        <p>{labels[0]}</p>
        <p>{labels[1]}</p>
      </div>
    </CardSurface>
  );
}

