  };
  const install = (item: MarketplaceItem) => {
    const next = installed.includes(item.id)
      ? installed.filter((id) => id !== item.id)
      : [...installed, item.id];
    change(next);
  };
  const open = (item: MarketplaceItem) => {
    setSelectedId(item.id);
    setCopied(false);
    if (scroll.current) scroll.current.scrollTop = 0;
  };
  const filtered = items.filter((i) =>
