          <IconButton
            ref={navigationTriggerRef}
            icon={RiMenuLine}
            className="lg:hidden"
            aria-label="Open navigation"
            aria-expanded={navigationOpen ?? false}
            onClick={onOpenNavigation}
          />
          <h1 className="px-1 text-title-2-medium whitespace-nowrap text-text-primary">
            {heading}
          </h1>
        </div>
        <div className="flex flex-wrap items-center justify-end gap-2.5">
          {actions !== undefined ? (
            actions
          ) : (
            <>
              <NotificationBell notifications={notifications} />
              <Button variant="secondary" leadingIcon={RiFilter3Fill} onClick={onFilters}>
                Filters
              </Button>
              <Button leadingIcon={RiAddLine} onClick={onAction}>
                {action}
              </Button>
            </>
          )}
        </div>
      </div>
    </header>
  );
}

// @zeus-internal
"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { cx } from "@/lib/cx";

export interface DialogLayerProps {
  isOpen: boolean;
  onClose: () => void;
  label: string;
  children: ReactNode;
  className?: string;
  /** Content that straddles the panel edge, outside its overflow clipping. */
  floatingContent?: ReactNode;
}

/** Shared portal, dismissal, surface and measured two-phase dialog presence. */
export function DialogLayer({
  isOpen,
  onClose,
  label,
  children,
  className,
  floatingContent,
}: DialogLayerProps) {
  const [mounted, setMounted] = useState(false);
  const [visible, setVisible] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let firstFrame = 0;
    let secondFrame = 0;
    let closeTimer: ReturnType<typeof setTimeout> | undefined;
    if (isOpen) {
      setMounted(true);
      firstFrame = requestAnimationFrame(() => {
        secondFrame = requestAnimationFrame(() => setVisible(true));
      });
    } else {
      setVisible(false);
      closeTimer = setTimeout(() => setMounted(false), 320);
    }
    return () => {
      cancelAnimationFrame(firstFrame);
      cancelAnimationFrame(secondFrame);
      if (closeTimer) clearTimeout(closeTimer);
    };
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKeyDown);
    panelRef.current?.focus();
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isOpen, onClose]);

  if (!mounted || typeof document === "undefined") return null;
  return createPortal(
    <div className="fixed inset-0 z-100 flex items-center justify-center p-4" role="presentation">
      <button
        type="button"
        aria-label={`Close ${label.toLowerCase()}`}
        tabIndex={-1}
        onClick={onClose}
        className={cx(
          "absolute inset-0 cursor-default bg-black/70 transition-opacity duration-300 ease-out",
          visible ? "opacity-100" : "opacity-0",
        )}
      />
      <div
        className={cx(
          "relative transform-gpu transition-[opacity,transform,filter] duration-300 ease-[cubic-bezier(0.32,0.72,0,1)] will-change-[opacity,transform,filter]",
          visible ? "scale-100 opacity-100 blur-0" : "scale-[0.85] opacity-0 blur-[4px]",
        )}
      >
        <div
          ref={panelRef}
          role="dialog"
          aria-modal="true"
          aria-label={label}
          tabIndex={-1}
          className={cx(
            "relative overflow-clip rounded-3xl bg-background-full shadow-xs outline-none",
            className,
          )}
        >
          {children}
        </div>
        {floatingContent}
      </div>
    </div>,
    document.body,
  );
}

// @zeus-internal
import { cx } from "@/lib/cx";
export const INPUT_FIELD_SURFACE = "relative flex w-full items-center rounded-2lg bg-background-tertiary-default text-foreground-icon-tertiary ring-2 ring-inset ring-transparent transition-[background-color,box-shadow,color] duration-[var(--input-transition-ms)] ease";
export function inputFieldStateClasses({ isFocusWithin, isHovered, isDisabled, isInvalid }: {
  isFocusWithin: boolean;
  isHovered: boolean;
  isDisabled: boolean;
  isInvalid: boolean;
}) {
  return cx(
    isHovered && !isFocusWithin && !isDisabled && !isInvalid && "ring-border-button-hover",
    isFocusWithin && !isDisabled && !isInvalid && "ring-border-button-active",
    isDisabled && "bg-input-disabled-background text-input-disabled-foreground",
    isInvalid && "bg-background-tertiary-error text-foreground-icon-error",
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};
const clientSnapshot = () => true;
const serverSnapshot = () => false;

/** Keep the first server/client render identical, then apply the user's motion preference. */
export function useHydratedReducedMotion(): boolean {
  const reduced = useReducedMotion();
  const hydrated = useSyncExternalStore(subscribe, clientSnapshot, serverSnapshot);
  return hydrated && reduced === true;
}

// @zeus-internal
"use client";

import { type RefObject, useEffect, useLayoutEffect, useState } from "react";

const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

interface SelectionBounds {
  left: number;
  top: number;
  width: number;
  height: number;
}

/** Keep selection chrome aligned when labels, fonts, items or container sizes change. */
export function useSelectionBounds(ref: RefObject<HTMLElement | null>, itemSelector: string) {
  const [bounds, setBounds] = useState<SelectionBounds | null>(null);
  useIsomorphicLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => {
      const selected = element.querySelector<HTMLElement>(`${itemSelector}[data-selected]`);
      const next = selected
        ? {
            left: selected.offsetLeft,
            top: selected.offsetTop,
            width: selected.offsetWidth,
            height: selected.offsetHeight,
          }
        : null;
      setBounds((previous) =>
        previous?.left === next?.left &&
        previous?.top === next?.top &&
        previous?.width === next?.width &&
        previous?.height === next?.height
          ? previous
          : next,
      );
    };
    const observed = new Set<HTMLElement>();
    const resize = new ResizeObserver(measure);
    resize.observe(element);
    const observeItems = () => {
      const items = new Set(element.querySelectorAll<HTMLElement>(itemSelector));
      for (const item of observed) {
        if (!items.has(item)) {
          resize.unobserve(item);
          observed.delete(item);
        }
      }
      for (const item of items) {
        if (!observed.has(item)) {
          observed.add(item);
          resize.observe(item);
        }
      }
      measure();
    };
    observeItems();
    const mutations = new MutationObserver(observeItems);
    mutations.observe(element, {
      attributes: true,
      attributeFilter: ["data-selected"],
      childList: true,
      characterData: true,
      subtree: true,
    });
    return () => {
      mutations.disconnect();
      resize.disconnect();
    };
  }, [ref, itemSelector]);
  return bounds;
}
